// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address newOwner, address other) public {
        vm.assume(newOwner != address(0));
        vm.assume(other != address(0));
        vm.assume(newOwner != address(this));

        // transfer ownership to newOwner (current owner is address(this))
        vm.prank(address(this));
        c.setOwner(newOwner);

        // the new owner can hand ownership on to `other`
        bool ok;
        vm.prank(newOwner);
        try c.setOwner(other) { ok = true; } catch { ok = false; }

        assertTrue(ok && c.owner() == other);
    }
}
